const express = require('express');

/**
 * Build the Express app against a given better-sqlite3 Database.
 * @param {import('better-sqlite3').Database} db
 */
function createApp(db) {
  const app = express();

  /**
   * OFFSET pagination — BROKEN under concurrent deletes.
   *
   * OFFSET is a position in the CURRENT result set. If rows are deleted
   * between requests, every surviving row shifts toward smaller offsets,
   * so a fixed offset skips rows that were never returned to the client.
   */
  app.get('/posts', (req, res) => {
    if ('after_id' in req.query) return keysetHandler(req, res, db);

    const limit = clampInt(req.query.limit, 1, 100, 20);
    const offset = clampInt(req.query.offset, 0, Number.MAX_SAFE_INTEGER, 0);

    const rows = db
      .prepare('SELECT id, title FROM posts ORDER BY id ASC LIMIT ? OFFSET ?')
      .all(limit, offset);

    res.json({ mode: 'offset', limit, offset, posts: rows });
  });

  /**
   * Keyset pagination — CORRECT under concurrent deletes.
   *
   * The cursor is a value from the last page ("give me everything AFTER
   * this id"), not a position. Deletes of earlier rows cannot affect it:
   * each surviving row is yielded exactly once across successive pages.
   */
  function keysetHandler(req, res, dbRef) {
    const limit = clampInt(req.query.limit, 1, 100, 20);
    const afterId = req.query.after_id === undefined || req.query.after_id === ''
      ? 0
      : asNonNegativeInt(req.query.after_id);
    if (!Number.isInteger(afterId)) {
      return res.status(400).json({ error: 'after_id must be a non-negative integer' });
    }

    const rows = dbRef
      .prepare('SELECT id, title FROM posts WHERE id > ? ORDER BY id ASC LIMIT ?')
      .all(afterId, limit);

    const nextAfterId = rows.length === limit ? rows[rows.length - 1].id : null;
    res.json({ mode: 'keyset', limit, after_id: afterId, next_after_id: nextAfterId, posts: rows });
  }

  // Convenience alias so keyset has a discoverable entry point too.
  app.get('/posts/keyset', (req, res) => keysetHandler(req, res, db));

  return app;
}

function asNonNegativeInt(v) {
  const n = Number(v);
  return Number.isInteger(n) && n >= 0 ? n : NaN;
}

function clampInt(v, min, max, fallback) {
  const n = Number(v ?? fallback);
  if (!Number.isInteger(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

module.exports = { createApp };
