const Database = require('better-sqlite3');
const fs = require('node:fs');

/**
 * Create the posts table (if needed) and seed with `count` posts.
 * @param {string|':memory:'} dbPath
 * @param {number} count
 */
function createDb(dbPath, { count = 60 } = {}) {
  if (dbPath !== ':memory:') fs.mkdirSync(require('node:path').dirname(dbPath), { recursive: true });
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');

  db.exec(`
    CREATE TABLE IF NOT EXISTS posts (
      id    INTEGER PRIMARY KEY,
      title TEXT NOT NULL
    )
  `);

  const insert = db.prepare('INSERT OR IGNORE INTO posts (id, title) VALUES (?, ?)');
  const seedAll = db.transaction((n) => {
    for (let i = 1; i <= n; i++) insert.run(i, `Post ${i}`);
  });
  const existing = db.prepare('SELECT COUNT(*) AS c FROM posts').get().c;
  if (existing < count) {
    // top up ids that may be missing (idempotent seeding)
    const have = new Set(db.prepare('SELECT id FROM posts').all().map((r) => r.id));
    for (let i = 1; i <= count; i++) if (!have.has(i)) insert.run(i, `Post ${i}`);
    void existing;
  }
  void seedAll;

  return db;
}

/** Delete a contiguous run of post ids. Returns the deleted ids. */
function deletePosts(db, fromId, toId) {
  const ids = [];
  const del = db.prepare('DELETE FROM posts WHERE id = ?');
  const tx = db.transaction(() => {
    for (let id = fromId; id <= toId; id++) del.run(id);
  });
  tx();
  for (let id = fromId; id <= toId; id++) ids.push(id);
  return ids;
}

module.exports = { createDb, deletePosts };
