const test = require('node:test');
const assert = require('node:assert/strict');
const request = require('supertest');

const { createDb, deletePosts } = require('./db');
const { createApp } = require('./app');

const LIMIT = 20;
const DELETED_RANGE = [3, 7]; // "5 early posts"

function setup() {
  const db = createDb(':memory:', { count: 60 });
  const app = createApp(db);
  return { db, app };
}

const idsOf = (res) => res.body.posts.map((p) => p.id);

test('[BUG DEMO] offset pagination skips 5 posts when early rows are deleted between pages', async () => {
  const { db, app } = setup();

  // Page 1: offset=0, limit=20 -> ids 1..20
  const page1 = await request(app).get('/posts').query({ offset: 0, limit: LIMIT }).expect(200);
  assert.deepEqual(idsOf(page1), Array.from({ length: 20 }, (_, i) => i + 1));

  // Concurrent mutation: 5 early posts vanish.
  const deleted = deletePosts(db, ...DELETED_RANGE);
  assert.equal(deleted.length, 5);

  // Client continues with a FIXED offset=20.
  const page2 = await request(app).get('/posts').query({ offset: 20, limit: LIMIT }).expect(200);

  const seen = new Set([...idsOf(page1), ...idsOf(page2)]);
  const survivors = new Set(
    db.prepare('SELECT id FROM posts').all().map((r) => r.id)
  );

  // PROOF of the skip: ids 21..25 still exist in the DB...
  for (let id = 21; id <= 25; id++) {
    assert.ok(survivors.has(id), `post ${id} was not deleted`);
    // ...were not on any page the client received...
    assert.ok(!seen.has(id), `client unexpectedly saw post ${id}`);
  }
  // ...and page2 jumped straight past them: it starts at id 26,
  // exactly 5 positions late because the 5 deletions shifted the set.
  const expectedPage2 = Array.from({ length: 20 }, (_, i) => i + 26); // 26..45
  assert.deepEqual(idsOf(page2), expectedPage2);

  const neverSeen = [...survivors].filter((id) => !seen.has(id)).sort((a, b) => a - b);
  assert.deepEqual(neverSeen, [21, 22, 23, 24, 25]);
});

